query getData($limit: Int!) {
  layer_images_connection(
    first: $limit
    where: {deleted_at: {_is_null: true}, _and: [{master: {_nilike: "%.svg"}}, {master: {_nilike: "%.gpx"}}], layer_image_category_id: {_eq: 37}}
    order_by: {id: desc}
  ) {
    edges {
      cursor
      node {
        id
        master
        url
        thumbnail
        name
        width
        height
        created_at
        layer_image_category_id
        __typename
      }
      __typename
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
      __typename
    }
    __typename
  }
}
